import{c as e,Q as s,j as a,m as r}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Start times","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/start-times.md","filePath":"user/event-setup/start-times.md"}'),o={name:"user/event-setup/start-times.md"};function n(i,t,h,l,d,c){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="start-times" tabindex="-1">Start times <a class="header-anchor" href="#start-times" aria-label="Permalink to &quot;Start times&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers allocating start times to competitors.</p><p>A competitor&#39;s <em>start time</em> is the clock time their race is measured from — their <em>race time</em> is simply finish minus start. This page explains where a start time can come from, how Manager decides which one to use when there&#39;s more than one, and what happens when you change a start time after competitors are already running.</p><blockquote><p><strong>Note:</strong> This page is about the <em>rules</em> — the sources of a start time and which one wins. The <strong>start draw</strong> (the tool that spaces individual start times at a regular interval and randomises the order) has its own page: <a href="./start-draw">Drawing start times</a>.</p></blockquote><h2 id="the-four-sources-of-a-start-time" tabindex="-1">The four sources of a start time <a class="header-anchor" href="#the-four-sources-of-a-start-time" aria-label="Permalink to &quot;The four sources of a start time&quot;">​</a></h2><p>A start time can come from any of four places:</p><table tabindex="0"><thead><tr><th>Source</th><th>Where it&#39;s set</th><th>Applies to</th></tr></thead><tbody><tr><td><strong>Individual allocated start</strong></td><td>The <a href="./start-draw">start draw</a>, an <a href="./import-event-data#start-list-iof-startlist-xml">import</a>, or the competitor&#39;s <strong>Edit competitor</strong> dialog</td><td>One competitor</td></tr><tr><td><strong>Class mass start</strong></td><td><strong>Edit Class</strong> dialog → <em>Start Time</em> section</td><td>Everyone in a class</td></tr><tr><td><strong>Event mass start</strong></td><td><strong>Edit</strong> event details → <strong>Starts</strong> tab</td><td>Everyone in the event</td></tr><tr><td><strong>Punched start</strong></td><td>The competitor punches a Start unit on the day</td><td>One competitor</td></tr></tbody></table><p>The first three are <em>allocated</em> — times you set in advance. The fourth is <em>punched</em> — recorded live when the competitor starts. They interact through a simple hierarchy.</p><h2 id="which-start-time-wins-the-hierarchy" tabindex="-1">Which start time wins: the hierarchy <a class="header-anchor" href="#which-start-time-wins-the-hierarchy" aria-label="Permalink to &quot;Which start time wins: the hierarchy&quot;">​</a></h2><p>For the <strong>allocated</strong> start time, the most specific level always beats the more general one:</p><ol><li><strong>Individual allocated start</strong> (highest priority)</li><li><strong>Class mass start</strong></li><li><strong>Event mass start</strong> (lowest priority)</li></ol><p>A competitor uses the highest level that&#39;s set for them. Someone with their own allocated time ignores any class or event mass start; someone with no individual time but whose class has a mass start uses that; otherwise they fall back to the event mass start (if the event has one and their class isn&#39;t excluded from it). If none of the three is set, the competitor has no allocated start — their time will come from a punch, or not at all.</p><p><strong>Example — a mass start event with two exceptions.</strong> Most of the field runs an event mass start at <strong>11:00</strong>, except the <em>Junior</em> class, which sets off as an earlier wave (a class mass start at <strong>10:45</strong>), and one course-checker, <em>Pat</em>, given an individual start of <strong>09:30</strong> to get round before the crowd:</p><table tabindex="0"><thead><tr><th>Competitor</th><th>Most specific setting they have</th><th>Start they get</th><th>Why</th></tr></thead><tbody><tr><td>Most of the field</td><td>Event mass start only</td><td><strong>11:00</strong></td><td>Nothing more specific is set</td></tr><tr><td>Anyone in <em>Junior</em></td><td>Class mass start (10:45)</td><td><strong>10:45</strong></td><td>Class mass start overrides the event mass start</td></tr><tr><td>Pat</td><td>Individual start (09:30)</td><td><strong>09:30</strong></td><td>An individual start overrides both mass starts</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Whether a <strong>punched start</strong> beats the allocated time is a separate question, decided by the <em>punching-start override</em> rather than the hierarchy. See <a href="#punched-starts">Punched starts</a> below.</p></blockquote><p>Manager resolves all of this for you automatically — you don&#39;t compute it by hand. Throughout the app the start time is shown with a small source label (<em>individual</em>, <em>class</em>, <em>event</em>, or <em>punched</em>) so you can always see where a competitor&#39;s time came from.</p><h2 id="event-mass-start" tabindex="-1">Event mass start <a class="header-anchor" href="#event-mass-start" aria-label="Permalink to &quot;Event mass start&quot;">​</a></h2><p>Use an event mass start when <strong>everyone starts together</strong> at one time.</p><p>Open the event dashboard, click <strong>Edit</strong> (event details), and go to the <strong>Starts</strong> tab. Switch on <strong>Mass Start</strong> and set the <strong>Mass Start Time</strong>. Every competitor whose class doesn&#39;t override it picks up this time.</p><h2 id="class-mass-start" tabindex="-1">Class mass start <a class="header-anchor" href="#class-mass-start" aria-label="Permalink to &quot;Class mass start&quot;">​</a></h2><p>Use a class mass start when <strong>one class starts together</strong> but the rest of the event doesn&#39;t — for example a beginners&#39; class that all sets off at once.</p><p>Open the <strong>Edit Class</strong> dialog (click the class on the <strong>Classes</strong> page), and in the <em>Start Time</em> section switch on <strong>Class mass start</strong> and set the time. A class mass start overrides the event mass start for that class, and is in turn overridden by any individual allocated time a competitor in the class has.</p><p>Two related controls in the same dialog:</p><ul><li><strong>Exclude this class from event mass start</strong> — shown only when the event has a mass start and this class has no class mass start of its own. Tick it to make the class start <em>individually</em> despite the event-wide mass start. (A class mass start already implies this, so the toggle only appears when there&#39;s no class mass start to make the point moot.)</li></ul><p><strong>Example — <em>Elite</em> opts out of the mass start.</strong> Your event has a mass start at <strong>10:00</strong> for the casual classes, but you want <em>Elite</em> to run individual drawn times instead. Tick <strong>Exclude this class from event mass start</strong> on Elite and run the <a href="./start-draw">draw</a> for it: Elite competitors get their drawn times, while everyone else still goes at 10:00.</p><blockquote><p><strong>Tip — running waves:</strong> Manager has no separate &quot;wave start&quot; feature, and it doesn&#39;t need one. To start groups in waves, give each class (or group of classes) its own <strong>class mass start</strong> at a staggered time — 10:00 for the first wave, 10:15 for the next, and so on. Each wave is just a class mass start at a different time.</p></blockquote><p>See <a href="./classes-and-courses">Classes and courses</a> for the full Edit Class dialog.</p><h2 id="individual-start-times" tabindex="-1">Individual start times <a class="header-anchor" href="#individual-start-times" aria-label="Permalink to &quot;Individual start times&quot;">​</a></h2><p>Individual allocated times sit at the top of the hierarchy, so they override any class or event mass start for that competitor. They reach Manager three ways:</p><ul><li><strong>The start draw</strong> — the usual way to produce a full individual start list. It spaces times at an interval and randomises the order. See <a href="./start-draw">Drawing start times</a>.</li><li><strong>Import</strong> — an <a href="./import-event-data#start-list-iof-startlist-xml">IOF StartList file</a>, an Eventor sync, or a CSV entry list can carry start times, which land as individual allocated times. See <a href="./import-event-data">Importing event data</a>.</li><li><strong>By hand</strong> — open a competitor&#39;s <strong>Edit competitor</strong> dialog. In the <em>Allocated/Mass Start Time</em> section the picker shows their individual time; the event and class mass starts that would otherwise apply are listed above it for reference. Set, change, or clear the time here. The time picker is a <strong>24-hour clock</strong> with seconds (so 1 pm is <code>13:00:00</code>), and defaults to <code>10:00:00</code>.</li></ul><p>Once a competitor&#39;s start time passes, Manager automatically marks them <strong>On Course</strong> even before any punch arrives — which is what the <a href="./../running-the-event/safety-check">safety check</a> relies on to know who&#39;s out in the forest.</p><h2 id="punched-starts" tabindex="-1">Punched starts <a class="header-anchor" href="#punched-starts" aria-label="Permalink to &quot;Punched starts&quot;">​</a></h2><p>At many events competitors start by punching a <strong>Start</strong> unit rather than to a fixed clock time. That punch is the <em>punched start</em>. It&#39;s how you run a <strong>start-when-ready</strong> event: don&#39;t allocate any times at all, and each competitor&#39;s start punch becomes their start time.</p><p>When a competitor has <em>both</em> an allocated time <em>and</em> a punched start, the <strong>punching-start override</strong> decides which wins. (When only one of the two exists, that one is always used — the override only matters when they disagree.) The override is set at three levels, most specific winning:</p><ol><li><strong>Per competitor</strong> — the <strong>On start punch</strong> dropdown in the competitor&#39;s <em>Allocated/Mass Start Time</em> section, with three choices: <ul><li><strong>Use event default</strong> — defer to the event setting (the default).</li><li><strong>Always use allocated start</strong> — ignore any start punch for this competitor.</li><li><strong>Allow punching start</strong> — the start punch wins; the allocated time is the fallback if no punch is recorded.</li></ul></li><li><strong>Per event</strong> — <strong>Allow punching starts to override allocated starts</strong> on the event&#39;s <strong>Starts</strong> tab. Applies to every competitor who&#39;s left on <em>Use event default</em>.</li><li><strong>New-event default</strong> — <strong>Punching starts override allocated starts</strong> on the global <a href="./../reference/settings">Settings</a> page, copied into each new event.</li></ol><p>The competitor dialog spells out the live result in plain language beneath the dropdown — for example <em>&quot;Start punch at 10:23:14 is used. Allocated start of 10:22:00 is the fallback.&quot;</em> or <em>&quot;Start time of 10:22:00 is used. Start punch at 10:23:14 is ignored.&quot;</em> — so you can confirm at a glance which time the competitor will be timed from.</p><p><strong>Example — late to the start.</strong> Your event leaves <strong>Allow punching starts to override allocated starts</strong> off, so allocated times win. <em>Robin</em> was drawn to start at <strong>10:14</strong> but was late to the start and was allowed to do a punching start at <strong>10:16:03</strong>:</p><ul><li>With the override off (the default here), Robin is timed from the drawn <strong>10:14</strong> — the two extra minutes are Robin&#39;s loss, exactly as a fixed start list intends.</li><li>Robin was late to the start through no fault of their own, so you open their <strong>Edit competitor</strong> dialog and set <strong>On start punch</strong> to <strong>Allow punching start</strong>. Now Robin is timed from the <strong>10:16:03</strong> punch, and 10:14 is kept only as a fallback in case no punch had been recorded.</li></ul><p>(If Robin had <em>no</em> allocated time at all — a start-when-ready event — the override wouldn&#39;t come into it: with nothing to conflict with, the punch is simply the start.)</p><p>Punched starts arrive when a card is read (see <a href="./../running-the-event/card-download">Downloading cards</a>) or via a radio Start control.</p><h2 id="when-you-change-a-start-time" tabindex="-1">When you change a start time <a class="header-anchor" href="#when-you-change-a-start-time" aria-label="Permalink to &quot;When you change a start time&quot;">​</a></h2><p>Start-time settings stay editable throughout the event, and Manager re-applies changes automatically — there&#39;s no recompute button. A change to the event mass start, a class mass start, an individual allocation, or an override flows through to the affected competitors within a few seconds.</p><p>What that means in practice:</p><ul><li><strong>Changing one level moves only the competitors who use it.</strong> Each competitor&#39;s start comes from a single source in the <a href="#which-start-time-wins-the-hierarchy">hierarchy</a>, so a change reaches just those competitors. In the score-event example above, nudging the 11:00 event mass start to 11:10 would move most of the field — but leave <em>Junior</em> (on its 10:45 class mass start) and <em>Pat</em> (on a 09:30 individual start) exactly where they are.</li><li><strong>Race times are recalculated for anyone already finished.</strong> Changing a start time is usually a <em>correction</em>, so Manager re-times finished competitors against the new start rather than ignoring the change.</li><li><strong>A start later than the finish has no valid race time.</strong> If a change would put a competitor&#39;s start <em>after</em> their finish punch, their race time can&#39;t be computed and Manager sets them to <strong>DNF</strong>. Watch for this if you push a morning class to an afternoon mass start after they&#39;ve already run.</li></ul><p>For working through a specific competitor whose time looks wrong, see <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a>.</p><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>24-hour clock.</strong> The time picker has no AM/PM — afternoon starts are <code>13:00:00</code>, <code>14:30:00</code>, and so on.</li><li><strong>A mass start that doesn&#39;t move everyone.</strong> If some competitors don&#39;t pick up the mass start you just set, they almost certainly have an <em>individual</em> allocated time (from an earlier draw or import) that overrides it — individual always wins. Clear those individual times if you want the mass start to apply. The <a href="./start-draw#classes-that-start-together-arent-drawn">start draw</a> counts them for you: it leaves a mass-start class out of the draw and says how many of its entrants still hold a start of their own.</li><li><strong>A class that&#39;s excluded — or not.</strong> A class with <strong>Exclude this class from event mass start</strong> ticked won&#39;t inherit the event mass start; a class you <em>expected</em> to start individually but didn&#39;t exclude will pick it up. Check the toggle when a class&#39;s start times surprise you.</li><li><strong>Punching override set the wrong way.</strong> Allocated times being ignored (or punches being ignored) usually traces back to the punching-start override — check the event&#39;s <strong>Starts</strong> tab and the competitor&#39;s <strong>On start punch</strong> choice.</li><li><strong>Start after finish.</strong> Setting a start time later than someone&#39;s finish drops them to DNF (see above).</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./start-draw">Drawing start times</a> — the tool that allocates individual start times in bulk</li><li><a href="./classes-and-courses">Classes and courses</a> — setting class mass starts and the event-mass-start exclude toggle</li><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a> — editing a single competitor&#39;s allocated start</li><li><a href="./import-event-data#start-list-iof-startlist-xml">Importing event data</a> — bringing start times in from a start-list file or Eventor</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — how a start time feeds into status and race time</li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a> — fixing a competitor whose start time is wrong</li></ul>',49)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
